local RiserBreakerMaker = {}
local PRODUCTS = {
    iron_riserbreaker = { name = "Železni lomilec pen", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni lomilec pen za livarje." },
    bronze_riserbreaker = { name = "Bronast lomilec pen", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast lomilec pen za livarje." },
    silver_riserbreaker = { name = "Srebrn lomilec pen", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn lomilec pen za livarje." },
    gilded_riserbreaker = { name = "Pozlačen lomilec pen", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen lomilec pen za livarje." },
    jewel_set_riserbreaker = { name = "Draguljast lomilec pen", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast lomilec pen za livarje." },
    royal_sovereign_riserbreaker = { name = "Kraljevski suveren lomilec pen", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren lomilec pen z biseri za krono." },
}
local BUILDINGS = {
    riserbreaker_workshop = { name = "Riserbreaker delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    riserbreaker_house = { name = "Riserbreaker hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_riserbreaker_atelier = { name = "Mojstrski riserbreaker atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_riserbreaker_palace = { name = "Suverena riserbreaker palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
RiserBreakerMaker.ironStock=18; RiserBreakerMaker.bronzeStock=14; RiserBreakerMaker.woodStock=10; RiserBreakerMaker.leatherStock=8; RiserBreakerMaker.silverStock=8; RiserBreakerMaker.goldStock=6; RiserBreakerMaker.jewelStock=4; RiserBreakerMaker.pearlStock=4
RiserBreakerMaker.productStock = {}; RiserBreakerMaker.buildings = {}; RiserBreakerMaker.maker = nil; RiserBreakerMaker.activeMaking = {}; RiserBreakerMaker.totalProducts = 0; RiserBreakerMaker.dayTimer = 0
function RiserBreakerMaker.init() RiserBreakerMaker.ironStock=18; RiserBreakerMaker.bronzeStock=14; RiserBreakerMaker.woodStock=10; RiserBreakerMaker.leatherStock=8; RiserBreakerMaker.silverStock=8; RiserBreakerMaker.goldStock=6; RiserBreakerMaker.jewelStock=4; RiserBreakerMaker.pearlStock=4; RiserBreakerMaker.productStock={}; RiserBreakerMaker.buildings={}; RiserBreakerMaker.maker=nil; RiserBreakerMaker.activeMaking={}; RiserBreakerMaker.totalProducts=0; RiserBreakerMaker.dayTimer=0; print("[RiserBreakerMaker] Royal Riser Breaker Maker System initialized (6 products, 4 buildings)") end
function RiserBreakerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; RiserBreakerMaker.maker={name=n or ("Penolomar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Penolomar najet: %s (spretnost: %d)",RiserBreakerMaker.maker.name,s),"success") end; return true end
function RiserBreakerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function RiserBreakerMaker.build(id) local ok,e=RiserBreakerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(RiserBreakerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function RiserBreakerMaker.getQualityBonus() local b=0; for _,bd in ipairs(RiserBreakerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function RiserBreakerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and RiserBreakerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and RiserBreakerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and RiserBreakerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and RiserBreakerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and RiserBreakerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and RiserBreakerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and RiserBreakerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and RiserBreakerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #RiserBreakerMaker.buildings==0 then return false,"Potrebna penolomna delavnica" end; if not RiserBreakerMaker.maker then return false,"Potreben penolomar" end; return true end
function RiserBreakerMaker.make(pt,qty) qty=qty or 1; local ok,e=RiserBreakerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then RiserBreakerMaker.ironStock=RiserBreakerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then RiserBreakerMaker.bronzeStock=RiserBreakerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then RiserBreakerMaker.woodStock=RiserBreakerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then RiserBreakerMaker.leatherStock=RiserBreakerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then RiserBreakerMaker.silverStock=RiserBreakerMaker.silverStock-d.silverCost*qty end; if d.goldCost then RiserBreakerMaker.goldStock=RiserBreakerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then RiserBreakerMaker.jewelStock=RiserBreakerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then RiserBreakerMaker.pearlStock=RiserBreakerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if RiserBreakerMaker.maker then t=math.max(1,t-math.floor(RiserBreakerMaker.maker.skill/13)) end; table.insert(RiserBreakerMaker.activeMaking,{id="riserbreaker_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function RiserBreakerMaker.completeMaking(m) local q=1.0+(RiserBreakerMaker.getQualityBonus()/100); if RiserBreakerMaker.maker then q=q+(RiserBreakerMaker.maker.skill/140) end; q=math.min(2.5,q); RiserBreakerMaker.productStock[m.productType]=(RiserBreakerMaker.productStock[m.productType] or 0)+m.quantity; RiserBreakerMaker.totalProducts=RiserBreakerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if RiserBreakerMaker.maker then RiserBreakerMaker.maker.itemsMade=RiserBreakerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then RiserBreakerMaker.maker.skill=math.min(100,RiserBreakerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Penolom izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"riserbreaker.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function RiserBreakerMaker.update(dt) if not _G.state then return end; RiserBreakerMaker.dayTimer=RiserBreakerMaker.dayTimer+dt; if RiserBreakerMaker.dayTimer>=30 then RiserBreakerMaker.dayTimer=0; for i=#RiserBreakerMaker.activeMaking,1,-1 do local m=RiserBreakerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then RiserBreakerMaker.completeMaking(m); table.remove(RiserBreakerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(RiserBreakerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if RiserBreakerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function RiserBreakerMaker.getStats() return {ironStock=RiserBreakerMaker.ironStock,bronzeStock=RiserBreakerMaker.bronzeStock,woodStock=RiserBreakerMaker.woodStock,leatherStock=RiserBreakerMaker.leatherStock,silverStock=RiserBreakerMaker.silverStock,goldStock=RiserBreakerMaker.goldStock,jewelStock=RiserBreakerMaker.jewelStock,pearlStock=RiserBreakerMaker.pearlStock,productStock=RiserBreakerMaker.productStock,numBuildings=#RiserBreakerMaker.buildings,hasMaker=RiserBreakerMaker.maker~=nil,makerName=RiserBreakerMaker.maker and RiserBreakerMaker.maker.name or "—",makerSkill=RiserBreakerMaker.maker and RiserBreakerMaker.maker.skill or 0,activeMaking=#RiserBreakerMaker.activeMaking,totalProducts=RiserBreakerMaker.totalProducts} end
return RiserBreakerMaker
